"""Fig4 full computation pipeline.

Single entry point. Runs former scripts in dependency order:
  1. fig4_subtype_predictions.py
  2. fig4_build_inputs.py
  3. fig4_mechanism.py
  4. fig4_drm_burden.py

Usage (from project root):
  python notebooks/scripts/fig4_compute.py
"""
from __future__ import annotations

from pathlib import Path

PROJ = Path(__file__).resolve().parent.parent.parent
SCRIPTS_DIR = Path(__file__).resolve().parent

STEPS: list[tuple[str, str]] = [
    ('fig4_subtype_predictions', '"""Reproducible Fig4 Subtype OOD predictions and clinical metrics.\n\nComputes B-train -> non-B-test predictions for binary mutation and\nESM-nonlinear models, then writes per-sample predictions, per-drug AUROC\nbootstrap CIs, threshold metrics, and representative-drug metrics used by\nnotebooks/fig4.ipynb.\n\nOutputs:\n  results/notebooks/fig4/fig4B_subtype_ood_auc_ci.csv\n  results/notebooks/fig4/fig4C_subtype_ood_clinical_metrics.csv\n  results/notebooks/fig4/fig4C_representative_clinical_metrics.csv\n  results/notebooks/fig4/fig4_subtype_ood_predictions.csv\n"""\nfrom __future__ import annotations\n\nimport json\nfrom pathlib import Path\n\nimport lightgbm as lgb\nimport numpy as np\nimport pandas as pd\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import confusion_matrix, roc_auc_score\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nimport sys\nsys.path.insert(0, str(Path(__file__).resolve().parent))\nfrom _common import make_binary_model as _cb, make_esm_lgb_model as _clgb, SEED as _SEED\n\nPROJ = Path(__file__).resolve().parent.parent.parent\nPREP = PROJ / "work" / "prepared"\nEMB = PROJ / "work" / "emb_full"\nREF_DIR = PROJ / "work" / "hivdb_full" / "refs"\nRES = PROJ / "work" / "results"\nOUT_DIR = PROJ / "results" / "notebooks" / "fig4"\nPROTOCOL_PATH = RES / "probe_protocol_full_selected_k.csv"\n\nSEED = 42\nN_BOOT = 1000\n\nGENE_OF = {"PI": "PR", "NRTI": "RT", "NNRTI": "RT", "INI": "IN"}\nDRUGS = {\n    "PI": ["FPV", "ATV", "IDV", "LPV", "NFV", "SQV", "TPV", "DRV"],\n    "NRTI": ["3TC", "ABC", "AZT", "D4T", "DDI", "TDF"],\n    "NNRTI": ["EFV", "ETR", "NVP", "RPV"],\n    "INI": ["RAL", "EVG", "DTG", "BIC", "CAB"],\n}\nMETHOD_LABEL = {"binary": "binary mutation", "esm_lgb": "ESM-nonlinear"}\n\n\ndef read_fasta_seq(path: Path) -> str:\n    return "".join(l.strip() for l in path.read_text().splitlines() if l and not l.startswith(">"))\n\n\ndef build_refs() -> dict[str, str]:\n    pol = read_fasta_seq(REF_DIR / "P04585.fasta")\n    spec = {\n        "PR": (pol, 489, 587, {3: "I"}),\n        "RT": (pol, 588, 1187, {214: "F", 570: "E"}),\n        "IN": (pol, 1148, 1435, {10: "E", 72: "I", 123: "S", 124: "T", 127: "K", 232: "D"}),\n    }\n    out = {}\n    for gene, (src, start, end, patch) in spec.items():\n        seq = list(src[start - 1:end])\n        for pos, aa in patch.items():\n            seq[pos - 1] = aa\n        out[gene] = "".join(seq)\n    return out\n\n\ndef binary_encode(seqs: list[str], ref: str) -> np.ndarray:\n    L = min(min(len(s) for s in seqs), len(ref))\n    X = np.zeros((len(seqs), L), dtype=np.float32)\n    for i, s in enumerate(seqs):\n        for j in range(L):\n            X[i, j] = float(s[j] != ref[j])\n    return X\n\n\ndef load_emb(gene: str) -> tuple[dict[str, int], np.ndarray]:\n    mean = np.load(EMB / f"{gene}_mean.npy")\n    seqs = json.load(open(EMB / f"{gene}_seqs.json"))["sequences"]\n    return {s: i for i, s in enumerate(seqs)}, mean\n\n\ndef make_binary_model():\n    return _cb()\n\n\ndef make_esm_lgb_model():\n    return _clgb()\n\n\ndef bootstrap_auc_ci(y, p, *, seed: int, n_boot: int = N_BOOT):\n    y = np.asarray(y, int)\n    p = np.asarray(p, float)\n    if len(np.unique(y)) < 2:\n        return np.nan, np.nan, np.nan\n    rng = np.random.default_rng(seed)\n    idx = np.arange(len(y))\n    vals = []\n    for _ in range(n_boot):\n        s = rng.choice(idx, size=len(idx), replace=True)\n        if len(np.unique(y[s])) >= 2:\n            vals.append(roc_auc_score(y[s], p[s]))\n    vals = np.asarray(vals)\n    return float(roc_auc_score(y, p)), float(np.percentile(vals, 2.5)), float(np.percentile(vals, 97.5))\n\n\ndef threshold_metrics(y, p, threshold: float = 0.5):\n    y = np.asarray(y, int)\n    pred = (np.asarray(p) >= threshold).astype(int)\n    tn, fp, fn, tp = confusion_matrix(y, pred, labels=[0, 1]).ravel()\n    sensitivity = tp / (tp + fn) if (tp + fn) else np.nan\n    specificity = tn / (tn + fp) if (tn + fp) else np.nan\n    ppv = tp / (tp + fp) if (tp + fp) else np.nan\n    return {"sensitivity": sensitivity, "specificity": specificity, "ppv": ppv, "tp": tp, "fp": fp, "tn": tn, "fn": fn}\n\n\ndef compute_predictions():\n    refs = build_refs()\n    emb_cache = {}\n    pred_rows, forest_rows, metric_rows = [], [], []\n    forest_seed_counter = 0\n\n    for cls, drugs in DRUGS.items():\n        gene = GENE_OF[cls]\n        if gene not in emb_cache:\n            emb_cache[gene] = load_emb(gene)\n        seq_to_i, mean = emb_cache[gene]\n        df = pd.read_csv(PREP / f"{cls}.csv", dtype={"SeqID": str, "PtID": str})\n        seqs_all = df["sequence"].tolist()\n        emb_row = np.array([seq_to_i.get(s, -1) for s in seqs_all])\n        st_all = df["Subtype"].fillna("Unknown").values\n        Xb_all = binary_encode(seqs_all, refs[gene])\n\n        for drug in drugs:\n            y = pd.to_numeric(df[f"{drug}_label"], errors="coerce").values\n            valid = (~np.isnan(y)) & (emb_row >= 0)\n            if valid.sum() == 0:\n                continue\n            yv = y[valid].astype(int)\n            st = st_all[valid]\n            is_nonB = (st != "B") & (st != "Unknown") & (st != "U")\n            if is_nonB.sum() < 10 or yv[is_nonB].sum() < 2 or (yv[is_nonB] == 0).sum() < 2 or len(np.unique(yv[~is_nonB])) < 2:\n                print(f"skip {cls}/{drug}: insufficient Subtype OOD test/train class counts", flush=True)\n                continue\n\n            Xb = Xb_all[valid]\n            Xe = mean[emb_row[valid]]\n            y_train, y_test = yv[~is_nonB], yv[is_nonB]\n            mb = make_binary_model()\n            me = make_esm_lgb_model()\n            mb.fit(Xb[~is_nonB], y_train)\n            me.fit(Xe[~is_nonB], y_train)\n            pb = mb.predict_proba(Xb[is_nonB])[:, 1]\n            pe = me.predict_proba(Xe[is_nonB])[:, 1]\n\n            for method, prob in [("binary", pb), ("esm_lgb", pe)]:\n                auc, lo, hi = bootstrap_auc_ci(y_test, prob, seed=SEED + forest_seed_counter)\n                forest_seed_counter += 1\n                mets = threshold_metrics(y_test, prob, threshold=0.5)\n                rec = {\n                    "class": cls,\n                    "drug": drug,\n                    "method": method,\n                    "method_label": METHOD_LABEL[method],\n                    "n": int(valid.sum()),\n                    "n_res": int(yv.sum()),\n                    "n_nonB": int(is_nonB.sum()),\n                    "n_nonB_res": int(y_test.sum()),\n                    "n_nonB_sus": int((y_test == 0).sum()),\n                    "auroc": auc,\n                    "ci_low": lo,\n                    "ci_high": hi,\n                    **mets,\n                }\n                forest_rows.append(rec)\n                metric_rows.append(rec.copy())\n\n            for i, (yy, pbb, pee) in enumerate(zip(y_test, pb, pe)):\n                pred_rows.append({\n                    "class": cls,\n                    "drug": drug,\n                    "row_in_test": i,\n                    "y_true": int(yy),\n                    "binary_prob": float(pbb),\n                    "esm_lgb_prob": float(pee),\n                })\n\n            print(\n                f"{cls}/{drug:4s} nonB={int(is_nonB.sum()):3d} "\n                f"R/S={int(y_test.sum())}/{int((y_test == 0).sum())} "\n                f"binary_auc={roc_auc_score(y_test, pb):.3f} esm_lgb_auc={roc_auc_score(y_test, pe):.3f}",\n                flush=True,\n            )\n\n    return pd.DataFrame(pred_rows), pd.DataFrame(forest_rows), pd.DataFrame(metric_rows)\n\n\ndef select_representative_metrics(forest: pd.DataFrame, metrics: pd.DataFrame) -> pd.DataFrame:\n    wide_auc = forest.pivot(index=["class", "drug", "n_res", "n_nonB"], columns="method", values="auroc").reset_index()\n    wide_auc["delta_auc"] = wide_auc["esm_lgb"] - wide_auc["binary"]\n    pi_control = (\n        wide_auc[wide_auc["class"] == "PI"]\n        .assign(abs_delta=lambda d: d["delta_auc"].abs())\n        .sort_values(["n_res", "abs_delta"], ascending=[False, True])\n        .head(1)\n    )\n    scarce_cut = wide_auc["n_res"].median()\n    scarce = wide_auc[wide_auc["n_res"] <= scarce_cut].sort_values("delta_auc", ascending=False).head(3)\n    selected = pd.concat([pi_control, scarce]).drop_duplicates(["class", "drug"])\n    selected_drugs = selected["drug"].tolist()\n    out = metrics[metrics["drug"].isin(selected_drugs)].copy()\n    out["drug"] = pd.Categorical(out["drug"], categories=selected_drugs, ordered=True)\n    return out.sort_values(["drug", "method"])\n\n\ndef main() -> None:\n    np.random.seed(SEED)\n    if not PROTOCOL_PATH.exists():\n        raise FileNotFoundError(f"Missing {PROTOCOL_PATH}. Run probe_protocol_full_selected_k.py first.")\n    OUT_DIR.mkdir(parents=True, exist_ok=True)\n\n    preds, forest, metrics = compute_predictions()\n    reps = select_representative_metrics(forest, metrics)\n\n    preds.to_csv(OUT_DIR / "fig4_subtype_ood_predictions.csv", index=False)\n    forest.to_csv(OUT_DIR / "fig4B_subtype_ood_auc_ci.csv", index=False)\n    metrics.to_csv(OUT_DIR / "fig4C_subtype_ood_clinical_metrics.csv", index=False)\n    reps.to_csv(OUT_DIR / "fig4C_representative_clinical_metrics.csv", index=False)\n\n    print("\\n===== Fig4 subtype OOD outputs =====")\n    print(f"predictions: {len(preds)} rows -> {OUT_DIR / \'fig4_subtype_ood_predictions.csv\'}")\n    print(f"forest:      {len(forest)} rows -> {OUT_DIR / \'fig4B_subtype_ood_auc_ci.csv\'}")\n    print(f"metrics:     {len(metrics)} rows -> {OUT_DIR / \'fig4C_subtype_ood_clinical_metrics.csv\'}")\n    print(f"rep metrics: {len(reps)} rows -> {OUT_DIR / \'fig4C_representative_clinical_metrics.csv\'}")\n\n\nif __name__ == "__main__":\n    main()\n'),
    ('fig4_build_inputs', '"""Build Fig4 intermediate tables from protocol + HIVDB Full fold-change files.\n\nGenerates:\n  fig4A_random_overestimate_vs_scarcity.csv\n  fig4_fc_extreme_by_drug.csv\n  fig4_barrier_fc_joined_metrics.csv\n  fig4_genetic_barrier_mannwhitney.csv\n\nDoes NOT regenerate PDB ligand distances (static structural asset):\n  fig4_ram_to_ligand_3d_distance.csv\n"""\nfrom __future__ import annotations\n\nimport sys\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nfrom scipy import stats\n\nsys.path.insert(0, str(Path(__file__).resolve().parent))\nfrom _common import DRUGS, FIG4_DIR, HIVDB_FULL, MAIN_CLASSES, PROTOCOL_CSV  # noqa: E402\n\nTHRESHOLDS = [10, 25, 50, 100]\n\n\ndef build_scarcity(protocol: pd.DataFrame) -> pd.DataFrame:\n    df = protocol.copy()\n    df["overestimate_esm_lgb"] = df["random_esm_lgb"] - df["ood_esm_lgb"]\n    df["overestimate_binary"] = df["random_binary"] - df["ood_binary"]\n    df["log10_n_res"] = np.log10(df["n_res"].clip(lower=1))\n    cols = [\n        "class", "drug", "gene", "n", "n_nonB", "n_res",\n        "random_esm_lgb", "ood_esm_lgb", "random_binary", "ood_binary",\n        "overestimate_esm_lgb", "overestimate_binary", "log10_n_res",\n    ]\n    return df[cols]\n\n\ndef build_fc_extreme() -> pd.DataFrame:\n    rows = []\n    for cls, drugs in DRUGS.items():\n        if cls not in MAIN_CLASSES:\n            continue\n        path = HIVDB_FULL / f"{cls}_DataSet.Full.txt"\n        if not path.exists():\n            continue\n        usecols = lambda c, drugs=set(drugs): c in drugs\n        raw = pd.read_csv(path, sep="\\t", usecols=usecols)\n        for drug in drugs:\n            if drug not in raw.columns:\n                continue\n            fc = pd.to_numeric(raw[drug], errors="coerce").dropna()\n            if fc.empty:\n                continue\n            rec = {\n                "class": cls,\n                "drug": drug,\n                "n_fc": int(len(fc)),\n                "median_fc": float(fc.median()),\n                "mean_fc": float(fc.mean()),\n                "p90_fc": float(fc.quantile(0.90)),\n                "p95_fc": float(fc.quantile(0.95)),\n                "max_fc": float(fc.max()),\n            }\n            for thr in THRESHOLDS:\n                mask = fc > thr\n                rec[f"prop_fc_gt_{thr}"] = float(mask.mean())\n                rec[f"n_fc_gt_{thr}"] = int(mask.sum())\n            rows.append(rec)\n    return pd.DataFrame(rows)\n\n\ndef build_joined(protocol: pd.DataFrame, fc: pd.DataFrame) -> pd.DataFrame:\n    df = protocol.copy()\n    df["overestimate"] = df["random_esm_lgb"] - df["ood_esm_lgb"]\n    df["esm_gain_ood"] = df["ood_esm_lgb"] - df["ood_binary"]\n    df["n_label"] = df["n"]\n    df["n_res_y"] = df["n_res"]\n    df["n_sus"] = df["n"] - df["n_res"]\n    # Class-level genetic barrier annotation used by fig4 (PI = high).\n    df["barrier_18_classlevel"] = np.where(df["class"] == "PI", "high", "low")\n    df["barrier_23_extended"] = df["barrier_18_classlevel"]\n    keep_fc = ["class", "drug", "prop_fc_gt_50", "p95_fc", "median_fc", "max_fc"]\n    out = df.merge(fc[keep_fc], on=["class", "drug"], how="left")\n    # placeholder mutation-burden fields (not required for primary tests)\n    for col in [\n        "mutation_hhi", "top1_mutation_burden", "top3_mutation_burden",\n        "top5_mutation_burden", "effective_mutation_positions",\n        "top_star_diff", "top_star_res_prev", "top_star_sus_prev",\n        "mean_res_entropy", "variable_res_entropy", "avg_res_hamming",\n    ]:\n        if col not in out.columns:\n            out[col] = np.nan\n    # rename n_res for compatibility with historical joined schema\n    out = out.rename(columns={"n_res": "n_res_x"})\n    return out\n\n\ndef mannwhitney(high: np.ndarray, low: np.ndarray, alternative: str) -> dict:\n    high = high[np.isfinite(high)]\n    low = low[np.isfinite(low)]\n    if len(high) == 0 or len(low) == 0:\n        return {\n            "high_n": len(high), "low_n": len(low),\n            "high_mean": np.nan, "high_median": np.nan,\n            "low_mean": np.nan, "low_median": np.nan,\n            "alternative": alternative, "p": np.nan,\n        }\n    stat = stats.mannwhitneyu(high, low, alternative=alternative)\n    return {\n        "high_n": int(len(high)),\n        "low_n": int(len(low)),\n        "high_mean": float(np.mean(high)),\n        "high_median": float(np.median(high)),\n        "low_mean": float(np.mean(low)),\n        "low_median": float(np.median(low)),\n        "alternative": alternative,\n        "p": float(stat.pvalue),\n    }\n\n\ndef build_barrier_tests(joined: pd.DataFrame) -> pd.DataFrame:\n    high = joined[joined["barrier_18_classlevel"] == "high"]\n    low = joined[joined["barrier_18_classlevel"] == "low"]\n    rows = []\n    for outcome, col in [("overestimate", "overestimate"), ("esm_gain_ood", "esm_gain_ood")]:\n        for alt in ["high less low", "high greater low"]:\n            alternative = "less" if "less" in alt else "greater"\n            rec = mannwhitney(high[col].to_numpy(float), low[col].to_numpy(float), alternative)\n            rows.append({\n                "annotation": "barrier_18_classlevel",\n                "outcome": outcome,\n                **rec,\n            })\n    return pd.DataFrame(rows)\n\n\ndef main() -> None:\n    if not PROTOCOL_CSV.exists():\n        raise FileNotFoundError(f"Missing {PROTOCOL_CSV}; run fig3_protocol_benchmark.py first")\n    FIG4_DIR.mkdir(parents=True, exist_ok=True)\n    protocol = pd.read_csv(PROTOCOL_CSV)\n    scarcity = build_scarcity(protocol)\n    fc = build_fc_extreme()\n    joined = build_joined(protocol, fc)\n    barrier = build_barrier_tests(joined)\n\n    scarcity.to_csv(FIG4_DIR / "fig4A_random_overestimate_vs_scarcity.csv", index=False)\n    fc.to_csv(FIG4_DIR / "fig4_fc_extreme_by_drug.csv", index=False)\n    joined.to_csv(FIG4_DIR / "fig4_barrier_fc_joined_metrics.csv", index=False)\n    barrier.to_csv(FIG4_DIR / "fig4_genetic_barrier_mannwhitney.csv", index=False)\n\n    ram = FIG4_DIR / "fig4_ram_to_ligand_3d_distance.csv"\n    if not ram.exists():\n        print(f"[WARN] static structural asset missing: {ram}")\n    print(f"saved scarcity={len(scarcity)} fc={len(fc)} joined={len(joined)} barrier={len(barrier)}")\n    print(f"→ {FIG4_DIR}")\n\n\nif __name__ == "__main__":\n    main()\n'),
    ('fig4_mechanism', '"""Fig4 mechanism statistics from precomputed protocol and phenotype outputs.\n\nThis script does not fit models. It joins existing Fig3/Fig4 protocol outputs,\ncomputes FC-threshold robustness summaries, and writes compact tables for the\nredesigned Fig4 mechanism panels.\n\nOutputs:\n  results/notebooks/fig4/fig4_mechanism_drug_metrics.csv\n  results/notebooks/fig4/fig4_fc_threshold_robustness.csv\n  results/notebooks/fig4/fig4_fc_threshold_correlations.csv\n  results/notebooks/fig4/fig4_fc_threshold_class_tests.csv\n  results/notebooks/fig4/fig4_summary_stats.csv\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Callable\n\nimport numpy as np\nimport pandas as pd\nfrom scipy import stats\n\nPROJ = Path(__file__).resolve().parent.parent.parent\nOUT_DIR = PROJ / "results" / "notebooks" / "fig4"\nPROTOCOL_PATH = PROJ / "work" / "results" / "probe_protocol_full_selected_k.csv"\nSCARCITY_PATH = OUT_DIR / "fig4A_random_overestimate_vs_scarcity.csv"\nOOD_AUC_PATH = OUT_DIR / "fig4B_subtype_ood_auc_ci.csv"\nFC_DRUG_PATH = OUT_DIR / "fig4_fc_extreme_by_drug.csv"\nJOINED_PATH = OUT_DIR / "fig4_barrier_fc_joined_metrics.csv"\nBARRIER_TEST_PATH = OUT_DIR / "fig4_genetic_barrier_mannwhitney.csv"\nRAM_DISTANCE_PATH = OUT_DIR / "fig4_ram_to_ligand_3d_distance.csv"\n\nSEED = 42\nN_BOOT = 5000\nTHRESHOLDS = (10, 25, 50)\nCLASS_ORDER = ("PI", "NRTI", "NNRTI", "INI")\nDRUGS = {\n    "PI": ["FPV", "ATV", "IDV", "LPV", "NFV", "SQV", "TPV", "DRV"],\n    "NRTI": ["3TC", "ABC", "AZT", "D4T", "DDI", "TDF"],\n    "NNRTI": ["EFV", "ETR", "NVP", "RPV"],\n    "INI": ["RAL", "EVG", "DTG", "BIC", "CAB"],\n}\nRAW_FC_FILES = {\n    "PI": PROJ / "work" / "hivdb_full" / "PI_DataSet.Full.txt",\n    "NRTI": PROJ / "work" / "hivdb_full" / "NRTI_DataSet.Full.txt",\n    "NNRTI": PROJ / "work" / "hivdb_full" / "NNRTI_DataSet.Full.txt",\n    "INI": PROJ / "work" / "hivdb_full" / "INI_DataSet.Full.txt",\n}\n\n\n@dataclass(frozen=True)\nclass TestRow:\n    category: str\n    metric: str\n    contrast: str\n    test: str\n    alternative: str\n    n: int | float\n    group1: str = ""\n    group2: str = ""\n    group1_n: int | float = np.nan\n    group2_n: int | float = np.nan\n    group1_mean: float = np.nan\n    group2_mean: float = np.nan\n    group1_median: float = np.nan\n    group2_median: float = np.nan\n    statistic: float = np.nan\n    odds_ratio: float = np.nan\n    p: float = np.nan\n    ci_low: float = np.nan\n    ci_high: float = np.nan\n    note: str = ""\n\n    def asdict(self) -> dict[str, object]:\n        return self.__dict__.copy()\n\n\ndef require(path: Path) -> Path:\n    if not path.exists():\n        raise FileNotFoundError(f"Missing required input: {path}")\n    return path\n\n\ndef read_csv(path: Path) -> pd.DataFrame:\n    return pd.read_csv(require(path))\n\n\ndef finite_pair(x: pd.Series, y: pd.Series) -> tuple[np.ndarray, np.ndarray]:\n    xv = pd.to_numeric(x, errors="coerce").to_numpy(float)\n    yv = pd.to_numeric(y, errors="coerce").to_numpy(float)\n    m = np.isfinite(xv) & np.isfinite(yv)\n    return xv[m], yv[m]\n\n\ndef safe_corr(x: np.ndarray, y: np.ndarray, method: str) -> tuple[float, float]:\n    if len(x) < 3 or np.nanstd(x) == 0 or np.nanstd(y) == 0:\n        return np.nan, np.nan\n    if method == "pearson":\n        r, p = stats.pearsonr(x, y)\n    elif method == "spearman":\n        r, p = stats.spearmanr(x, y)\n    else:\n        raise ValueError(method)\n    return float(r), float(p)\n\n\ndef bootstrap_corr_ci(x: np.ndarray, y: np.ndarray, method: str, *, seed: int = SEED, n_boot: int = N_BOOT) -> tuple[float, float]:\n    if len(x) < 4:\n        return np.nan, np.nan\n    rng = np.random.default_rng(seed)\n    vals: list[float] = []\n    n = len(x)\n    for _ in range(n_boot):\n        idx = rng.integers(0, n, n)\n        r, _ = safe_corr(x[idx], y[idx], method)\n        if np.isfinite(r):\n            vals.append(r)\n    if len(vals) < max(50, n_boot // 20):\n        return np.nan, np.nan\n    return float(np.percentile(vals, 2.5)), float(np.percentile(vals, 97.5))\n\n\ndef mean_median(vals: pd.Series) -> tuple[float, float]:\n    v = pd.to_numeric(vals, errors="coerce").dropna()\n    if len(v) == 0:\n        return np.nan, np.nan\n    return float(v.mean()), float(v.median())\n\n\ndef add_summary_row(rows: list[dict[str, object]], row: TestRow) -> None:\n    rows.append(row.asdict())\n\n\ndef build_drug_metrics() -> pd.DataFrame:\n    protocol = read_csv(PROTOCOL_PATH).copy()\n    fc = read_csv(FC_DRUG_PATH).copy()\n    joined = read_csv(JOINED_PATH).copy()\n\n    protocol["random_overestimate_esm_lgb"] = protocol["random_esm_lgb"] - protocol["ood_esm_lgb"]\n    protocol["random_overestimate_binary"] = protocol["random_binary"] - protocol["ood_binary"]\n    protocol["esm_ood_gain"] = protocol["ood_esm_lgb"] - protocol["ood_binary"]\n    protocol["esm_random_gain"] = protocol["random_esm_lgb"] - protocol["random_binary"]\n\n    fc_cols = [\n        "class", "drug", "n_fc", "median_fc", "mean_fc", "p90_fc", "p95_fc", "max_fc",\n        "prop_fc_gt_10", "n_fc_gt_10", "prop_fc_gt_25", "n_fc_gt_25", "prop_fc_gt_50", "n_fc_gt_50",\n    ]\n    metrics = protocol.merge(fc[fc_cols], on=["class", "drug"], how="left")\n\n    joined_cols = [\n        "class", "drug", "n_label", "n_sus", "mutation_hhi", "top1_mutation_burden",\n        "top3_mutation_burden", "top5_mutation_burden", "effective_mutation_positions",\n        "mean_res_entropy", "variable_res_entropy", "avg_res_hamming",\n        "barrier_18_classlevel", "barrier_23_extended",\n    ]\n    for col in joined_cols:\n        if col not in joined.columns:\n            joined[col] = np.nan\n    metrics = metrics.merge(joined[joined_cols], on=["class", "drug"], how="left")\n    # The precomputed Fig4 barrier test table labels the primary class-level\n    # contrast as high_n=8 / low_n=15. Recreate a plotting group that matches\n    # those summary statistics exactly: PI as high, all non-PI tasks as low.\n    # Keep the original barrier_18_classlevel and barrier_23_extended columns\n    # unchanged for traceability.\n    metrics["barrier_primary_plot_group"] = np.where(metrics["class"] == "PI", "high", "low")\n\n    order = {cls: i for i, cls in enumerate(CLASS_ORDER)}\n    drug_order = {(cls, drug): j for cls, drugs in DRUGS.items() for j, drug in enumerate(drugs)}\n    metrics["class_order"] = metrics["class"].map(order)\n    metrics["drug_order"] = [drug_order.get((r["class"], r["drug"]), 999) for _, r in metrics.iterrows()]\n    metrics = metrics.sort_values(["class_order", "drug_order"]).drop(columns=["class_order", "drug_order"])\n    return metrics\n\n\ndef build_fc_threshold_long(metrics: pd.DataFrame) -> pd.DataFrame:\n    rows: list[dict[str, object]] = []\n    for _, r in metrics.iterrows():\n        for threshold in THRESHOLDS:\n            prop_col = f"prop_fc_gt_{threshold}"\n            n_col = f"n_fc_gt_{threshold}"\n            if prop_col not in metrics.columns or pd.isna(r.get(prop_col, np.nan)):\n                continue\n            rows.append({\n                "class": r["class"],\n                "drug": r["drug"],\n                "threshold": threshold,\n                "n_fc": r.get("n_fc", np.nan),\n                "n_extreme": r.get(n_col, np.nan),\n                "prop_extreme": r.get(prop_col, np.nan),\n                "random_overestimate_esm_lgb": r.get("random_overestimate_esm_lgb", np.nan),\n                "esm_ood_gain": r.get("esm_ood_gain", np.nan),\n                "barrier_18_classlevel": r.get("barrier_18_classlevel", np.nan),\n                "barrier_23_extended": r.get("barrier_23_extended", np.nan),\n                "barrier_primary_plot_group": r.get("barrier_primary_plot_group", np.nan),\n            })\n    return pd.DataFrame(rows)\n\n\ndef compute_fc_correlations(fc_long: pd.DataFrame) -> pd.DataFrame:\n    rows: list[dict[str, object]] = []\n    outcomes = ["random_overestimate_esm_lgb", "esm_ood_gain"]\n    for threshold in THRESHOLDS:\n        d = fc_long[fc_long["threshold"] == threshold]\n        for outcome in outcomes:\n            x, y = finite_pair(d["prop_extreme"], d[outcome])\n            for method in ("pearson", "spearman"):\n                r, p = safe_corr(x, y, method)\n                lo, hi = bootstrap_corr_ci(x, y, method, seed=SEED + threshold + (0 if outcome == outcomes[0] else 100))\n                rows.append({\n                    "threshold": threshold,\n                    "outcome": outcome,\n                    "method": method,\n                    "n_drugs": len(x),\n                    "r": r,\n                    "p": p,\n                    "ci_low": lo,\n                    "ci_high": hi,\n                })\n    return pd.DataFrame(rows)\n\n\ndef mannwhitney_row(\n    data: pd.DataFrame,\n    metric: str,\n    mask1: pd.Series,\n    mask2: pd.Series,\n    *,\n    category: str,\n    contrast: str,\n    group1: str,\n    group2: str,\n    alternative: str,\n    note: str = "",\n) -> TestRow:\n    x = pd.to_numeric(data.loc[mask1, metric], errors="coerce").dropna()\n    y = pd.to_numeric(data.loc[mask2, metric], errors="coerce").dropna()\n    g1_mean, g1_med = mean_median(x)\n    g2_mean, g2_med = mean_median(y)\n    if len(x) == 0 or len(y) == 0:\n        stat = p = np.nan\n    else:\n        stat, p = stats.mannwhitneyu(x, y, alternative=alternative)\n    return TestRow(\n        category=category,\n        metric=metric,\n        contrast=contrast,\n        test="mannwhitneyu",\n        alternative=alternative,\n        n=int(len(x) + len(y)),\n        group1=group1,\n        group2=group2,\n        group1_n=int(len(x)),\n        group2_n=int(len(y)),\n        group1_mean=g1_mean,\n        group2_mean=g2_mean,\n        group1_median=g1_med,\n        group2_median=g2_med,\n        statistic=float(stat) if np.isfinite(stat) else np.nan,\n        p=float(p) if np.isfinite(p) else np.nan,\n        note=note,\n    )\n\n\ndef compute_drug_level_class_tests(metrics: pd.DataFrame, fc_long: pd.DataFrame) -> pd.DataFrame:\n    rows: list[dict[str, object]] = []\n\n    for threshold in THRESHOLDS:\n        d = fc_long[fc_long["threshold"] == threshold]\n        for contrast, mask1, mask2, group1, group2 in [\n            ("NNRTI_vs_PI", d["class"] == "NNRTI", d["class"] == "PI", "NNRTI", "PI"),\n            ("NNRTI_vs_others", d["class"] == "NNRTI", d["class"] != "NNRTI", "NNRTI", "others"),\n        ]:\n            row = mannwhitney_row(\n                d,\n                "prop_extreme",\n                mask1,\n                mask2,\n                category="fc_threshold_drug_level",\n                contrast=f"{contrast}_fc_gt_{threshold}",\n                group1=group1,\n                group2=group2,\n                alternative="greater",\n                note="Drug-level FC extreme proportion; strict > threshold.",\n            )\n            rows.append(row.asdict())\n\n    return pd.DataFrame(rows)\n\n\ndef raw_fc_values_by_class() -> dict[str, pd.Series]:\n    out: dict[str, pd.Series] = {}\n    for cls, path in RAW_FC_FILES.items():\n        df = pd.read_csv(require(path), sep="\\t", usecols=lambda c, drugs=set(DRUGS[cls]): c in drugs)\n        vals = []\n        for drug in DRUGS[cls]:\n            if drug in df.columns:\n                vals.append(pd.to_numeric(df[drug], errors="coerce"))\n        if vals:\n            out[cls] = pd.concat(vals, ignore_index=True).dropna()\n        else:\n            out[cls] = pd.Series(dtype=float)\n    return out\n\n\ndef compute_measurement_level_fc_tests() -> pd.DataFrame:\n    rows: list[dict[str, object]] = []\n    fc = read_csv(FC_DRUG_PATH)\n\n    for threshold in THRESHOLDS:\n        n_col = f"n_fc_gt_{threshold}"\n        if n_col not in fc.columns:\n            continue\n        class_counts: dict[str, tuple[int, int]] = {}\n        for cls in CLASS_ORDER:\n            d = fc[fc["class"] == cls]\n            n = int(pd.to_numeric(d["n_fc"], errors="coerce").fillna(0).sum())\n            extreme = int(pd.to_numeric(d[n_col], errors="coerce").fillna(0).sum()) if len(d) else 0\n            class_counts[cls] = (extreme, n - extreme)\n            if n == 0:\n                continue\n            rows.append({\n                "category": "fc_threshold_measurement_count",\n                "metric": "fc_extreme_count",\n                "contrast": f"{cls}_fc_gt_{threshold}",\n                "test": "count",\n                "alternative": "",\n                "threshold": threshold,\n                "level": "measurement_sum_18drugs",\n                "group1": cls,\n                "group2": "",\n                "group1_n": n,\n                "group2_n": np.nan,\n                "group1_extreme": extreme,\n                "group1_non_extreme": n - extreme,\n                "group2_extreme": np.nan,\n                "group2_non_extreme": np.nan,\n                "group1_mean": extreme / n if n else np.nan,\n                "group2_mean": np.nan,\n                "group1_median": np.nan,\n                "group2_median": np.nan,\n                "statistic": np.nan,\n                "odds_ratio": np.nan,\n                "p": np.nan,\n                "ci_low": np.nan,\n                "ci_high": np.nan,\n                "note": "Summed from fig4_fc_extreme_by_drug.csv across the 18 modeled PI/NRTI/NNRTI drugs with available FC data; not patient-deduplicated.",\n            })\n\n        contrasts = {\n            "NNRTI_vs_PI": ["PI"],\n            "NNRTI_vs_NRTI": ["NRTI"],\n            "NNRTI_vs_PI_NRTI": ["PI", "NRTI"],\n            "NNRTI_vs_all_other_available_fc": ["PI", "NRTI"],\n        }\n        n_ext, n_non = class_counts.get("NNRTI", (0, 0))\n        for contrast, other_classes in contrasts.items():\n            o_ext = sum(class_counts.get(c, (0, 0))[0] for c in other_classes)\n            o_non = sum(class_counts.get(c, (0, 0))[1] for c in other_classes)\n            table = np.array([[n_ext, n_non], [o_ext, o_non]], dtype=int)\n            if table.sum() == 0 or (table[0].sum() == 0) or (table[1].sum() == 0):\n                odds, p = np.nan, np.nan\n            else:\n                odds, p = stats.fisher_exact(table, alternative="greater")\n            rows.append({\n                "category": "fc_threshold_measurement_level",\n                "metric": "fc_extreme_proportion",\n                "contrast": f"{contrast}_fc_gt_{threshold}",\n                "test": "fisher_exact",\n                "alternative": "greater",\n                "threshold": threshold,\n                "level": "measurement_sum_18drugs",\n                "group1": "NNRTI",\n                "group2": "+".join(other_classes),\n                "group1_n": int(n_ext + n_non),\n                "group2_n": int(o_ext + o_non),\n                "group1_extreme": int(n_ext),\n                "group1_non_extreme": int(n_non),\n                "group2_extreme": int(o_ext),\n                "group2_non_extreme": int(o_non),\n                "group1_mean": n_ext / (n_ext + n_non) if (n_ext + n_non) else np.nan,\n                "group2_mean": o_ext / (o_ext + o_non) if (o_ext + o_non) else np.nan,\n                "group1_median": np.nan,\n                "group2_median": np.nan,\n                "statistic": np.nan,\n                "odds_ratio": float(odds) if np.isfinite(odds) else np.nan,\n                "p": float(p) if np.isfinite(p) else np.nan,\n                "ci_low": np.nan,\n                "ci_high": np.nan,\n                "note": "Fisher test on FC measurement counts summed from the 18 modeled PI/NRTI/NNRTI drug-level FC table; not patient-deduplicated.",\n            })\n    return pd.DataFrame(rows)\n\n\ndef compute_summary_stats(metrics: pd.DataFrame, scarcity: pd.DataFrame, ram: pd.DataFrame) -> pd.DataFrame:\n    rows: list[dict[str, object]] = []\n\n    # Scarcity checks retained as non-primary evidence.\n    x, y = finite_pair(scarcity["n_res"], scarcity["overestimate_esm_lgb"])\n    for method in ("pearson", "spearman"):\n        r, p = safe_corr(x, y, method)\n        add_summary_row(rows, TestRow(\n            category="scarcity_nonprimary",\n            metric="overestimate_esm_lgb_vs_n_res",\n            contrast="n_res_vs_random_overestimate",\n            test=method,\n            alternative="two-sided",\n            n=len(x),\n            statistic=r,\n            p=p,\n            note="Borderline/unstable; not used as main Fig4 mechanism claim.",\n        ))\n\n    # ESM OOD gain concentration in NRTI/INI.\n    ni = metrics[metrics["class"].isin(["NRTI", "INI"])]\n    pn = metrics[metrics["class"].isin(["PI", "NNRTI"])]\n    rows.append(mannwhitney_row(\n        metrics,\n        "esm_ood_gain",\n        metrics["class"].isin(["NRTI", "INI"]),\n        metrics["class"].isin(["PI", "NNRTI"]),\n        category="esm_ood_gain_main",\n        contrast="NRTI_INI_vs_PI_NNRTI",\n        group1="NRTI+INI",\n        group2="PI+NNRTI",\n        alternative="greater",\n        note="Main Fig4 finding: OOD AUROC(ESM-nonlinear) - OOD AUROC(binary).",\n    ).asdict())\n    for label, d in [("NRTI_INI", ni), ("PI_NNRTI", pn)]:\n        vals = pd.to_numeric(d["esm_ood_gain"], errors="coerce").dropna()\n        if len(vals) > 0:\n            stat, p = stats.wilcoxon(vals, alternative="greater", zero_method="wilcox")\n            rows.append(TestRow(\n                category="esm_ood_gain_main",\n                metric="esm_ood_gain",\n                contrast=f"{label}_greater_than_zero",\n                test="wilcoxon_signed_rank",\n                alternative="greater",\n                n=int(len(vals)),\n                group1=label,\n                group1_n=int(len(vals)),\n                group1_mean=float(vals.mean()),\n                group1_median=float(vals.median()),\n                statistic=float(stat),\n                p=float(p),\n                note="One-sample signed-rank test of drug-level ESM OOD gain > 0.",\n            ).asdict())\n\n    # Random CV overestimate class heterogeneity.\n    class_vals = [metrics.loc[metrics["class"] == cls, "random_overestimate_esm_lgb"].dropna() for cls in CLASS_ORDER]\n    stat, p = stats.kruskal(*class_vals)\n    rows.append(TestRow(\n        category="random_cv_overestimate",\n        metric="random_overestimate_esm_lgb",\n        contrast="drug_class_global",\n        test="kruskal",\n        alternative="two-sided",\n        n=int(sum(len(v) for v in class_vals)),\n        statistic=float(stat),\n        p=float(p),\n        note="Global four-class test; interpreted with planned NNRTI > PI contrast.",\n    ).asdict())\n    rows.append(mannwhitney_row(\n        metrics,\n        "random_overestimate_esm_lgb",\n        metrics["class"] == "NNRTI",\n        metrics["class"] == "PI",\n        category="random_cv_overestimate",\n        contrast="NNRTI_vs_PI",\n        group1="NNRTI",\n        group2="PI",\n        alternative="greater",\n        note="Planned contrast.",\n    ).asdict())\n\n    # Primary conservative plotting/summary contrast follows the existing\n    # fig4_genetic_barrier_mannwhitney.csv main rows (high_n=8, low_n=15):\n    # PI as high-barrier reference, all non-PI tasks as low/intermediate for\n    # this Figure-4 mechanism contrast. The raw 18-drug label is kept in the\n    # output table but would exclude INI from the low group.\n    barrier = metrics[metrics["barrier_primary_plot_group"].isin(["high", "low"])]\n    for metric in ("random_overestimate_esm_lgb", "esm_ood_gain"):\n        rows.append(mannwhitney_row(\n            barrier,\n            metric,\n            barrier["barrier_primary_plot_group"] == "high",\n            barrier["barrier_primary_plot_group"] == "low",\n            category="genetic_barrier_primary",\n            contrast="high_vs_low",\n            group1="high",\n            group2="low",\n            alternative="less",\n            note="Primary Fig4 barrier contrast matching precomputed high_n=8/low_n=15 summary; high=PI, low=non-PI.",\n        ).asdict())\n\n    # RAM-to-ligand distance.\n    dist_col = "min_heavy_atom_distance_A"\n    ram_groups = [ram.loc[ram["target"] == t, dist_col].dropna() for t in ["PR", "RT_NRTI", "RT_NNRTI", "IN"] if t in set(ram["target"])]\n    if len(ram_groups) >= 2:\n        stat, p = stats.kruskal(*ram_groups)\n        rows.append(TestRow(\n            category="structure_context",\n            metric="ram_to_ligand_min_distance_A",\n            contrast="target_global",\n            test="kruskal",\n            alternative="two-sided",\n            n=int(sum(len(g) for g in ram_groups)),\n            statistic=float(stat),\n            p=float(p),\n            note="Representative PDB/RAM-list analysis; mechanism context, not sole proof.",\n        ).asdict())\n    for target, series in ram.groupby("target")[dist_col]:\n        vals = series.dropna()\n        rows.append(TestRow(\n            category="structure_context_summary",\n            metric="ram_to_ligand_min_distance_A",\n            contrast=f"{target}_median",\n            test="summary",\n            alternative="",\n            n=int(len(vals)),\n            group1=str(target),\n            group1_n=int(len(vals)),\n            group1_mean=float(vals.mean()),\n            group1_median=float(vals.median()),\n            note="Distance in angstroms; lower means closer to representative ligand heavy atoms.",\n        ).asdict())\n\n    return pd.DataFrame(rows)\n\n\ndef write_outputs() -> None:\n    OUT_DIR.mkdir(parents=True, exist_ok=True)\n    metrics = build_drug_metrics()\n    fc_long = build_fc_threshold_long(metrics)\n    corr = compute_fc_correlations(fc_long)\n    drug_tests = compute_drug_level_class_tests(metrics, fc_long)\n    meas_tests = compute_measurement_level_fc_tests()\n    class_tests = pd.concat([drug_tests, meas_tests], ignore_index=True, sort=False)\n    scarcity = read_csv(SCARCITY_PATH)\n    ram = read_csv(RAM_DISTANCE_PATH)\n    summary = compute_summary_stats(metrics, scarcity, ram)\n\n    # Add selected FC Fisher rows into the compact summary for easy annotation.\n    keep_fc = meas_tests[\n        (meas_tests["test"] == "fisher_exact")\n        & (meas_tests["contrast"].isin([f"NNRTI_vs_PI_NRTI_fc_gt_{t}" for t in THRESHOLDS] + [f"NNRTI_vs_all_other_available_fc_fc_gt_{t}" for t in THRESHOLDS]))\n    ].copy()\n    if len(keep_fc):\n        keep_fc = keep_fc.reindex(columns=summary.columns, fill_value=np.nan)\n        summary = pd.concat([summary, keep_fc], ignore_index=True, sort=False)\n\n    metrics.to_csv(OUT_DIR / "fig4_mechanism_drug_metrics.csv", index=False)\n    fc_long.to_csv(OUT_DIR / "fig4_fc_threshold_robustness.csv", index=False)\n    corr.to_csv(OUT_DIR / "fig4_fc_threshold_correlations.csv", index=False)\n    class_tests.to_csv(OUT_DIR / "fig4_fc_threshold_class_tests.csv", index=False)\n    summary.to_csv(OUT_DIR / "fig4_summary_stats.csv", index=False)\n\n    protocol_n = len(pd.read_csv(PROTOCOL_PATH))\n    fc_n = len(pd.read_csv(FC_DRUG_PATH))\n    joined_fc = int(metrics["n_fc"].notna().sum())\n    missing_fc = metrics.loc[metrics["n_fc"].isna(), ["class", "drug"]]\n\n    print("\\n===== Fig4 mechanism outputs =====")\n    print(f"protocol drugs: {protocol_n}")\n    print(f"FC drug rows:   {fc_n}")\n    print(f"joined FC rows: {joined_fc}")\n    if len(missing_fc):\n        print("missing FC drugs:", ", ".join(f"{r[\'class\']}/{r[\'drug\']}" for _, r in missing_fc.iterrows()))\n    print(f"drug metrics:   {len(metrics)} rows -> {OUT_DIR / \'fig4_mechanism_drug_metrics.csv\'}")\n    print(f"FC robustness:  {len(fc_long)} rows -> {OUT_DIR / \'fig4_fc_threshold_robustness.csv\'}")\n    print(f"correlations:   {len(corr)} rows -> {OUT_DIR / \'fig4_fc_threshold_correlations.csv\'}")\n    print(f"class tests:    {len(class_tests)} rows -> {OUT_DIR / \'fig4_fc_threshold_class_tests.csv\'}")\n    print(f"summary stats:  {len(summary)} rows -> {OUT_DIR / \'fig4_summary_stats.csv\'}")\n\n    print("\\n===== Key checks =====")\n    key = summary[\n        summary["contrast"].isin([\n            "NRTI_INI_vs_PI_NNRTI",\n            "NNRTI_vs_PI",\n            "high_vs_low",\n            "target_global",\n            "n_res_vs_random_overestimate",\n            "NNRTI_vs_PI_NRTI_fc_gt_50",\n            "NNRTI_vs_all_other_fc_gt_50",\n        ])\n    ]\n    cols = [c for c in ["category", "metric", "contrast", "test", "alternative", "n", "group1_mean", "group2_mean", "group1_median", "group2_median", "odds_ratio", "statistic", "p"] if c in key.columns]\n    print(key[cols].to_string(index=False))\n\n\nif __name__ == "__main__":\n    write_outputs()\n'),
    ('fig4_drm_burden', '"""\nfig4_drm_burden.py\n===========================\n计算 fig4D 所需的高耐药记录 DRM 负担统计。\n\n输入（必须已存在）：\n  work/hivdb_full/PI_DataSet.Full.txt\n  work/hivdb_full/NNRTI_DataSet.Full.txt\n\n输出（写入 results/notebooks/fig4/）：\n  fig4E_high_fc_drm_burden_measurements.csv  -- 每条高 FC 记录的逐药 DRM 计数\n  fig4E_high_fc_drm_burden_by_drug.csv       -- 每药汇总统计 + Mann-Whitney 注释\n\n运行方式（从项目根目录）：\n  python notebooks/scripts/fig4_drm_burden.py\n"""\n\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nfrom scipy import stats\n\n# ── path discovery ────────────────────────────────────────────────────────\nCWD = Path(__file__).resolve().parent.parent.parent\nPROJECT_ROOT = CWD if (CWD / "work" / "hivdb_full").exists() else CWD.parent\nassert (PROJECT_ROOT / "work" / "hivdb_full").exists(), (\n    f"Cannot locate work/hivdb_full from {CWD}."\n)\n\nOUT_DIR = PROJECT_ROOT / "results" / "notebooks" / "fig4"\nOUT_DIR.mkdir(parents=True, exist_ok=True)\n\nRAW_FC_MUTATION_FILES = {\n    "PI":    PROJECT_ROOT / "work" / "hivdb_full" / "PI_DataSet.Full.txt",\n    "NNRTI": PROJECT_ROOT / "work" / "hivdb_full" / "NNRTI_DataSet.Full.txt",\n}\n\nFIG4E_DRUGS = {\n    "PI":    ["FPV", "ATV", "IDV", "LPV", "NFV", "SQV", "TPV", "DRV"],\n    "NNRTI": ["EFV", "NVP", "ETR", "RPV", "DOR"],\n}\n\n# Drug-major DRM positions (from repo/src/interpretability.py; DOR added for HIVDB Full)\nDRUG_MAJOR_DRM_POSITIONS: dict[str, dict[str, set[int]]] = {\n    "PI": {\n        "ATV": {32, 33, 46, 47, 48, 50, 54, 82, 84, 88, 90},\n        "DRV": {32, 33, 47, 50, 54, 76, 84, 89},\n        "FPV": {32, 33, 46, 47, 50, 54, 76, 82, 84},\n        "IDV": {32, 46, 47, 54, 76, 82, 84},\n        "LPV": {32, 33, 46, 47, 48, 50, 54, 76, 82, 84},\n        "NFV": {30, 46, 84, 88, 90},\n        "SQV": {48, 54, 82, 84, 90},\n        "TPV": {33, 47, 58, 74, 82, 83, 84},\n    },\n    "NNRTI": {\n        "EFV": {100, 101, 103, 106, 108, 181, 188, 190, 225},\n        "ETR": {100, 101, 106, 138, 179, 181, 190, 230},\n        "NVP": {100, 101, 103, 106, 108, 181, 188, 190},\n        "RPV": {100, 101, 138, 179, 181, 221, 230},\n        "DOR": {106, 108, 181, 188, 190, 221, 227, 230, 234, 236},\n    },\n}\n\n\ndef _require(path: Path) -> Path:\n    if not path.exists():\n        raise FileNotFoundError(f"Missing required input: {path}")\n    return path\n\n\ndef is_observed_mutation(value: object) -> bool:\n    if pd.isna(value):\n        return False\n    return str(value).strip() not in {"", "-", "."}\n\n\ndef compute_high_fc_drm_burden(\n    threshold: float = 50.0,\n) -> tuple[pd.DataFrame, pd.DataFrame]:\n    """\n    For each drug in FIG4E_DRUGS, find isolates with FC > threshold and\n    compute how many drug-major DRM positions are mutated.\n\n    Returns (measurement_df, drug_df).\n    """\n    measurement_rows: list[dict] = []\n    drug_rows: list[dict] = []\n\n    for cls, path in RAW_FC_MUTATION_FILES.items():\n        _require(path)\n        drugs       = FIG4E_DRUGS[cls]\n        drm_by_drug = DRUG_MAJOR_DRM_POSITIONS[cls]\n        needed      = {"SeqID", "PtID", "Subtype", "CompMutList", *drugs}\n        needed     |= {f"P{pos}" for pos_set in drm_by_drug.values() for pos in pos_set}\n\n        raw = pd.read_csv(path, sep="\\t", usecols=lambda c: c in needed)\n\n        for drug in drugs:\n            if drug not in raw.columns:\n                continue\n            fc    = pd.to_numeric(raw[drug], errors="coerce")\n            valid = fc.notna()\n            high  = valid & (fc > threshold)\n\n            drm_positions = sorted(pos for pos in drm_by_drug[drug] if f"P{pos}" in raw.columns)\n            drm_cols      = [f"P{pos}" for pos in drm_positions]\n            if not drm_cols:\n                continue\n\n            high_mut    = raw.loc[high, drm_cols].map(is_observed_mutation)\n            high_counts = high_mut.sum(axis=1).astype(int)\n\n            for idx, count in high_counts.items():\n                measurement_rows.append({\n                    "class":                    cls,\n                    "drug":                     drug,\n                    "SeqID":                    raw.loc[idx, "SeqID"],\n                    "PtID":                     raw.loc[idx, "PtID"],\n                    "Subtype":                  raw.loc[idx, "Subtype"] if "Subtype" in raw.columns else "",\n                    "fc":                       float(fc.loc[idx]),\n                    "fc_threshold":             threshold,\n                    "drug_major_drm_count":     int(count),\n                    "n_drug_major_drm_positions": int(len(drm_positions)),\n                    "drug_major_drm_positions": ";".join(map(str, drm_positions)),\n                })\n\n            n_valid = int(valid.sum())\n            n_high  = int(high.sum())\n            drug_rows.append({\n                "class":                              cls,\n                "drug":                               drug,\n                "fc_threshold":                       threshold,\n                "n_valid_fc_records":                 n_valid,\n                "n_high_fc_records":                  n_high,\n                "prop_high_fc_records":               n_high / n_valid if n_valid else np.nan,\n                "mean_drug_major_drm_count_high_fc":  float(high_counts.mean())            if n_high else np.nan,\n                "median_drug_major_drm_count_high_fc":float(high_counts.median())          if n_high else np.nan,\n                "mean_drug_major_drm_frac_high_fc":   (float(high_counts.mean())   / len(drm_positions)) if (n_high and drm_positions) else np.nan,\n                "median_drug_major_drm_frac_high_fc": (float(high_counts.median()) / len(drm_positions)) if (n_high and drm_positions) else np.nan,\n                "n_drug_major_drm_positions":         int(len(drm_positions)),\n                "drug_major_drm_positions":           ";".join(map(str, drm_positions)),\n            })\n\n    measurement_df = pd.DataFrame(measurement_rows)\n    drug_df        = pd.DataFrame(drug_rows)\n\n    # Sort to match original notebook order\n    order_map = {\n        (cls, drug): i\n        for cls, drugs in FIG4E_DRUGS.items()\n        for i, drug in enumerate(drugs)\n    }\n    drug_df["class_order"] = drug_df["class"].map({"PI": 0, "NNRTI": 1})\n    drug_df["drug_order"]  = [order_map.get((r["class"], r["drug"]), 999) for _, r in drug_df.iterrows()]\n    drug_df = (drug_df\n               .sort_values(["class_order", "drug_order"])\n               .drop(columns=["class_order", "drug_order"])\n               .reset_index(drop=True))\n\n    return measurement_df, drug_df\n\n\n# ── entry point ───────────────────────────────────────────────────────────\n\nif __name__ == "__main__":\n    print("Computing high-FC DRM burden (threshold FC > 50) …")\n    measurements, drug_summary = compute_high_fc_drm_burden(threshold=50.0)\n\n    out_m = OUT_DIR / "fig4E_high_fc_drm_burden_measurements.csv"\n    out_d = OUT_DIR / "fig4E_high_fc_drm_burden_by_drug.csv"\n    measurements.to_csv(out_m, index=False)\n    drug_summary.to_csv(out_d, index=False)\n    print(f"  Saved → {out_m.relative_to(PROJECT_ROOT)}  ({len(measurements)} rows)")\n    print(f"  Saved → {out_d.relative_to(PROJECT_ROOT)}  ({len(drug_summary)} rows)")\n\n    print("\\nPer-drug summary:")\n    display_cols = [\n        "class", "drug", "n_valid_fc_records", "n_high_fc_records",\n        "prop_high_fc_records", "mean_drug_major_drm_count_high_fc",\n        "mean_drug_major_drm_frac_high_fc",\n    ]\n    print(drug_summary[display_cols].round(3).to_string(index=False))\n\n    pi_frac    = drug_summary.loc[drug_summary["class"] == "PI",    "mean_drug_major_drm_frac_high_fc"].dropna()\n    nnrti_frac = drug_summary.loc[drug_summary["class"] == "NNRTI", "mean_drug_major_drm_frac_high_fc"].dropna()\n    if len(pi_frac) and len(nnrti_frac):\n        _, p_val = stats.mannwhitneyu(pi_frac, nnrti_frac, alternative="greater")\n        print(f"\\nPI > NNRTI drug-level Mann-Whitney p = {p_val:.4g}")\n        print("NOTE: drug-level test treats each drug as one point; within-class")\n        print("      cross-resistance makes drugs correlated (pseudoreplication).")\n\n    print("\\nDone.")\n'),
]

def _run_embedded(name: str, source: str) -> None:
    """Run embedded former-script source with a virtual __file__ under scripts/.

    Downstream scripts resolve project paths via Path(__file__).parent.parent.parent,
    so __file__ must look like notebooks/scripts/<name>.py.
    """
    virtual_file = str(SCRIPTS_DIR / f"{name}.py")
    glb = {
        "__name__": "__main__",
        "__file__": virtual_file,
        "__builtins__": __builtins__,
    }
    print(f"\n===== [{name}] start =====", flush=True)
    exec(compile(source, virtual_file, "exec"), glb, glb)
    print(f"===== [{name}] done =====\n", flush=True)


def main() -> None:
    if not (PROJ / "work").exists():
        raise SystemExit(f"Cannot locate project work/ from {PROJ}")
    for name, source in STEPS:
        _run_embedded(name, source)
    print(f"All steps in {Path(__file__).name} finished.")


if __name__ == "__main__":
    main()
